{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "A higher general-warranty cap, with a clear calculation and aggregation mechanism"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "a tipping basket (recovery from dollar one once crossed), sensible de minimis and aggregation of related claims"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "General warranties should survive at least 24 months"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Give fundamental title/capacity warranties a separate, substantially higher cap—typically up to the purchase price—and longer survival."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve separate contractual rights and remedies for specific indemnities, price/debt adjustments and fraud or deliberate concealment."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Exclude general disclosure of the data room and public records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit any knowledge defence to actual knowledge of named Buyer personnel, without constructive or imputed knowledge"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "A condition precedent requiring final, unconditional written consent and evidence that all conditions in clause 11.3 are satisfied or waived, effective at Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Repayment at or before Completion, lender payout evidence, executed releases and discharge of security as Completion deliverables."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "explicit treatment in the funds flow and completion accounts—normally as a Seller-funded payment or agreed debt-like adjustment, without double counting."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Add a specific indemnity for loss arising from failure to obtain the materials or rights"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for incident-related liabilities and reasonable investigation, remediation and notification costs, with suitable cap and survival treatment."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "DD-008 and DD-011 together record three renewals totalling AUD 330,000, but do not establish whether they are unavoidable, terminable, accrued or ordinary-course."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Limit warranty-specific restrictions to warranty claims. Preserve separate contractual rights and remedies for specific indemnities, price/debt adjustments and fraud or deliberate concealment."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012’s share register is evidence of the registered holder, not by itself proof of clean title or complete corporate ownership."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Do not accept the Seller’s assertion that these are settled under the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

